static int socket_reset ( struct pcmcia_socket * skt ) { int status , i ; dev_dbg ( & skt -> dev , "reset\n" ) ; skt -> socket . flags |= SS_OUTPUT_ENA | SS_RESET ; udelay ( ( long ) reset_time ) ; skt -> socket . flags &= ~ SS_RESET ; skt -> ops -> set_socket ( skt , & skt -> socket ) ; msleep ( unreset_delay * 10 ) ; for ( i = 0 ; i < unreset_limit ; i ++ ) { skt -> ops -> get_status ( skt , & status ) ; if ( ! ( status & SS_DETECT ) ) { return - ENODEV ; } if ( status & SS_READY ) { return 0 ; } msleep ( unreset_check * 10 ) ; } dev_err ( & skt -> dev , "time out after reset\n" ) ; return - ETIMEDOUT ; } 